@import url("chrome://messenger/skin/messenger.css");

#abContactsPanel {
  appearance: none;
  background-color: -moz-Dialog;
  background-image: none !important;
  color: -moz-dialogText;
  text-shadow: none;

  &:not([lwt-tree]) {
    --button-background: rgba(128, 128, 128, 0.15);
    --button-background-hover: rgba(128, 128, 128, 0.25);
    --button-background-active: rgba(128, 128, 128, 0.35);
    --box-text-color: MenuText;
    --box-background-color: Menu;
    --box-border-color: ThreeDShadow;
    --field-border-color: rgba(128, 128, 128, 0.6);
  }

  &[lwt-tree] {
    background-color: var(--toolbar-background-color);
    color: var(--lwt-text-color);
  }
}

#AbPickerHeader {
  margin: 0 3px;
  gap: 3px;

  & #abContextMenuButton {
    min-inline-size: unset;
    inline-size: 24px;
    min-block-size: 24px;
    margin: 0;
    padding: 0;
    list-style-image: var(--icon-more);
    -moz-context-properties: stroke;
    stroke: currentColor;

    & .button-text {
      display: none;
    }
  }

  & #addressbookList {
    margin: 0;

    &::part(label-box) {
      inline-size: 0; /* Make the label crop if necessary. */
    }
  }
}

#peopleSearchInput {
  margin: 0 3px;

  & [slot="search-button"] {
    content: var(--icon-search);
  }
}

#abResultsTree {
  border-block: 1px solid var(--sidebar-border);

  & .tree-table {
    inline-size: 100%;
  }
}
